// Fontes e limitações (#/evidencias) — design Evidence: what each badge means, every data source with
// checksums, the independent checks (PGDA, JPL Horizons) and the known limits. Read straight from data/.
// Source of truth: this .tsx file (Preact). evidencias.js is generated by `npm --prefix web run build:ts`.
// Kept imperative: the pgvector search result list is re-rendered by the submit handler, outside the first render.
import { h } from "../../vendor/preact/preact.module.js";
import { num } from "../../ds/components.js";
import { buildHash } from "../../ds/router.js";
import { Badge, LayerCard, mount } from "../../ds/ui.js";
import { loadSites } from "../data.js";
// @ts-ignore TS7016: JS module without types
import { mountVectorSearch } from "../../moonproof/screens/vector-search.js";
const getJSON = (url) => fetch(url).then(r => (r.ok ? r.json() : null), () => null);
const short = (n) => n.replace(/\s*\(.*\)$/, "");
const link = (url, text) => (url ? h("a", { href: url, rel: "noopener", target: "_blank" }, text || url) : h("span", { class: "t3" }, "N/D"));
export async function render(outlet, ctx) {
    const data = await loadSites();
    const [pgda, hor, meta] = await Promise.all([
        getJSON("./data/validation/validation_pgda.json"), getJSON("./data/validation/validation_horizons.json"),
        getJSON("./data/" + data.sites[0].series + ".json")
    ]);
    const prov = meta && meta.provenance;
    const siteName = (id) => short((data.sites.find(s => s.id === id) || { name: id }).name);
    mount(outlet, h("div", { class: "ev stack" },
        h("div", { class: "page-head" },
            h("div", null,
                h("p", { class: "lbl-s" }, "Evid\u00EAncias"),
                h("h1", { "data-route-title": "" }, "Fontes e limita\u00E7\u00F5es"))),
        h("section", { class: "solid card" },
            h("h2", { class: "h-card" }, "Como ler os selos"),
            h("dl", { class: "seals" },
                h("dt", null,
                    h(Badge, { kind: "val" })),
                h("dd", null, "Produto oficial NASA/JPL usado como refer\u00EAncia (ex.: PGDA, Horizons)."),
                h("dt", null,
                    h(Badge, { kind: "est" })),
                h("dd", null, "Calculado por n\u00F3s a partir de dado real (LOLA + SPICE). Pr\u00E9vio, n\u00E3o revisado pela NASA."),
                h("dt", null,
                    h(Badge, { kind: "sim" })),
                h("dd", null, "Simula\u00E7\u00E3o ou dado sint\u00E9tico (painel de bordo, laborat\u00F3rio de pouso)."),
                h("dt", null,
                    h(Badge, { kind: "nd" })),
                h("dd", null, "N\u00E3o dispon\u00EDvel ou n\u00E3o calculado. Nunca mostramos 0 no lugar de um valor ausente."))),
        h("div", { class: "cards2" },
            h(LayerCard, { title: "Compara\u00E7\u00E3o com NASA PGDA", badge: "val", answer: pgda ? "Diferença de Sol entre " + num(Math.min(...pgda.results.map(r => r.diff_sun_pp)), 1) + " e " + num(Math.max(...pgda.results.map(r => r.diff_sun_pp)), 1) + " pontos percentuais nos " + pgda.results.length + " locais." : "N/D", why: pgda ? h("ul", { class: "t2" }, pgda.caveats.map(c => h("li", null, c))) : "Arquivo de validação indisponível.", proof: pgda ? pgda.results.map((r) => [siteName(r.site),
                    "Sol " + num(r.pipeline_mean_solar_disc_pct, 1) + "% vs " + num(r.pgda_avg_solar_disc_pct, 1) + "% · Terra " + num(r.pipeline_earth_centre_pct, 1) + "% vs " + num(r.pgda_avg_earth_any_part_pct, 1) + "%"]) : [] }),
            h(LayerCard, { title: "Confer\u00EAncia com JPL Horizons", badge: "val", answer: hor ? "Maior diferença de elevação: " + num(Math.max(...hor.results.flatMap(r => r.comparisons.map(c => c.max_abs_el_diff_deg))), 3) + "° em " + hor.results.reduce((n, r) => n + r.comparisons.reduce((m, c) => m + c.n, 0), 0) + " comparações." : "N/D", why: hor ? "Datas espalhadas pela janela 2025–2028 conferidas com a API do JPL Horizons (" + hor.reference + ")." : "Arquivo de validação indisponível.", proof: hor ? hor.results.map((r) => [siteName(r.site),
                    r.comparisons.map(c => (c.body === "sun" ? "Sol" : "Terra") + " Δel " + num(c.max_abs_el_diff_deg, 3) + "°, Δaz·cos " + num(c.max_abs_az_diff_deg_cos_el, 3) + "°").join(" · ")]) : [] })),
        h("section", { class: "solid card tablewrap" },
            h("h2", { class: "h-card" }, "Fontes dos dados"),
            h("table", { class: "mtab" },
                h("thead", null,
                    h("tr", null,
                        h("th", { scope: "col" }, "Dado"),
                        h("th", { scope: "col" }, "Fonte"),
                        h("th", { scope: "col" }, "Verifica\u00E7\u00E3o"))),
                h("tbody", null,
                    h("tr", null,
                        h("th", { scope: "row" }, "Relevo"),
                        h("td", null, prov ? prov.terrain : "N/D"),
                        h("td", { class: "mono small" }, prov ? "SHA-256 " + prov.terrain_sha256.slice(0, 16) + "…" : "N/D")),
                    prov ? Object.entries(prov.kernel_sha256).map(([k, sha]) => h("tr", null,
                        h("th", { scope: "row" }, "Efem\u00E9ride"),
                        h("td", null, link(prov.kernel_sources && prov.kernel_sources[k], k)),
                        h("td", { class: "mono small" }, "SHA-256 " + sha.slice(0, 16) + "…"))) : [],
                    data.sites.map(s => h("tr", null,
                        h("th", { scope: "row" }, short(s.name)),
                        h("td", null, link(s.source_url, s.source)),
                        h("td", { class: "small" }, num(s.lat, 2, "°") + ", " + num(s.lon, 2, "°") + " · centro de catálogo")))))),
        h("section", { class: "solid card", id: "metadata-search" }),
        h("section", { class: "solid card" },
            h("h2", { class: "h-card" }, "Limita\u00E7\u00F5es"),
            h("ul", { class: "t2" },
                h("li", null, "Status científico: " + data.raw.science_status + " (prévio, não validado de forma independente)."),
                h("li", null, data.raw.note),
                h("li", null, "Sol e Terra s\u00E3o pontos (centro do disco) contra o horizonte LOLA; sem refra\u00E7\u00E3o, sem antena, sem r\u00E1dio."),
                h("li", null, "Energia e bateria n\u00E3o s\u00E3o calculadas para locais reais (N/D). O painel de bordo usa um modelo sint\u00E9tico (SIM)."),
                h("li", null, "O sombreado do mapa \u00E9 ilustrativo (hillshade), n\u00E3o \u00E9 simula\u00E7\u00E3o de ilumina\u00E7\u00E3o."),
                h("li", null, "Sem recomenda\u00E7\u00E3o de voo. A NASA n\u00E3o endossa esta ferramenta.")),
            h("p", null,
                h("a", { class: "chipg", href: buildHash("/bordo/status", { site: ctx.site }) }, "Status do painel de bordo \u2192")))));
    const vector = outlet.querySelector("#metadata-search");
    if (vector)
        mountVectorSearch(vector, { locale: "pt-BR" });
}
